@php($payload=$trackingPayload)
@php($money=fn($n)=>app(\App\Support\StorefrontCurrencyContext::class)->formatSnapshot($n,$payload['currency'],$payload['currencyExchangeRate']??1))
<header class="bk-tracking-result-header"><h1>Track your order</h1><p>Order {{ $payload['number'] }}</p><span class="bk-status">{{ $payload['statusLabel'] }}</span></header>
@php($stage=match(strtolower($payload['statusLabel'])){'delivered'=>4,'shipped','in transit'=>3,'processing'=>2,default=>0})
<ol class="bk-tracking-stages">@foreach(['Order created','Payment confirmed','Processing','Shipped','Delivered'] as $index=>$label)<li @class(['complete'=>$index<$stage,'current'=>$index===$stage])><span>{{ $index<$stage && ($index!==1 || collect($payload['timeline'])->contains(fn($e)=>str_contains(strtolower($e['title']), 'payment')))?'✓':($index+1) }}</span>{{ $label }}</li>@endforeach</ol>
<section class="bk-tracking-items"><h2>Order items</h2>@foreach($payload['items'] as $item)<article><img src="{{ $item['imageUrl']?:asset('images/image-not-found.png') }}" alt="{{ $item['title'] }}"><div><h3>{{ $item['title'] }}</h3><p>{{ $item['variantTitle'] }}</p><p>Qty: {{ $item['quantity'] }}</p></div><strong>{{ $money($item['lineTotal']) }}</strong></article>@endforeach</section>
<div class="bk-tracking-info"><section><h3>Order details</h3><p>Order status: {{ $payload['statusLabel'] }}</p>@if($payload['tracking']['number'])<p>Tracking number: {{ $payload['tracking']['number'] }}</p>@endif @if($payload['tracking']['carrier'])<p>Courier: {{ $payload['tracking']['carrier'] }}</p>@endif</section><section><h3>Shipping address</h3>@if($payload['address']??null)<address>{{ $payload['address']['line1'] }}<br>{{ $payload['address']['city'] }} {{ $payload['address']['postalCode'] }}</address>@else<p>Address unavailable.</p>@endif</section><section><h3>Total</h3><dl>@foreach(['subtotal'=>'Subtotal','discount'=>'Discount','shipping'=>'Shipping','tax'=>'Tax','total'=>'Total'] as $key=>$label)@if(in_array($key,['subtotal','shipping','total'])||($payload['totals'][$key]??0))<div><dt>{{ $label }}</dt><dd>{{ $money($payload['totals'][$key]??0) }}</dd></div>@endif@endforeach</dl></section></div>
<section class="bk-tracking-updates"><h2>Shipping updates</h2>@forelse($payload['timeline'] as $event)<article><h3>{{ $event['title'] }}</h3>@if($event['timestamp'])<time>{{ \Carbon\Carbon::parse($event['timestamp'])->format('d M Y H:i') }}</time>@endif<p>{{ $event['description'] }}</p>@if($event['location'])<small>{{ $event['location'] }}</small>@endif</article>@empty<p>No shipping updates yet.</p>@endforelse</section><a class="bk-primary bk-tracking-continue" href="{{ route('storefront.index') }}">Continue shopping →</a>
